local M=require('retgtk.core');return function(p) local w=M.widget('slider',p);function w:paint(r,c) local lo,hi=self.min or 0,self.max or 1;assert(hi>lo);local _,_,held=M.control(self,r,c);if held then local x=imm_pointer();self:set('value',lo+(hi-lo)*math.max(0,math.min(1,(x-r.x)/r.w))) end;imm_rect(r.x,r.y+r.h-4,r.w*math.max(0,math.min(1,(self.value-lo)/(hi-lo))),4,c.theme.accent) end;return w end
